package pe.vichaval.gestionriego.parcela.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.vichaval.gestionriego.agricultor.repository.AgricultorRepository;import pe.vichaval.gestionriego.parcela.dto.ParcelaForm;import pe.vichaval.gestionriego.parcela.entity.Parcela;import pe.vichaval.gestionriego.parcela.repository.ParcelaRepository;import pe.vichaval.gestionriego.riego.repository.TurnoRiegoRepository;
@Service @Transactional public class ParcelaService { private final ParcelaRepository p;private final AgricultorRepository a;private final TurnoRiegoRepository t;public ParcelaService(ParcelaRepository p,AgricultorRepository a,TurnoRiegoRepository t){this.p=p;this.a=a;this.t=t;} @Transactional(readOnly=true) public Parcela get(Long id){return p.findById(id).orElseThrow(()->new IllegalArgumentException("Parcela no encontrada"));} public void guardar(ParcelaForm f,Long id){if(id==null&&p.existsByCodigoIgnoreCase(f.getCodigo()))throw new IllegalArgumentException("Codigo duplicado");if(id!=null&&p.existsByCodigoIgnoreCaseAndIdNot(f.getCodigo(),id))throw new IllegalArgumentException("Codigo duplicado");var ag=a.findById(f.getAgricultorId()).orElseThrow();if(!"ACTIVO".equals(ag.getEstado()))throw new IllegalStateException("El agricultor esta inactivo");Parcela x=id==null?new Parcela(f,ag):get(id);if(id!=null)x.actualizar(f,ag);p.save(x);} public void eliminar(Long id){if(t.countByParcelaId(id)>0)throw new IllegalStateException("La parcela tiene turnos asociados; cambiala a INACTIVA");p.delete(get(id));} }
